const make=(id,goal,terms,steps,worked,practice,check,sources,links)=>({id,goal,terms:terms.map(([name,meaning])=>({name,meaning})),steps:steps.map(([title,...body])=>({title,body})),worked,practice:{action:practice[0],expected:practice[1],trouble:practice[2]},check:{prompt:check[0],options:check[1],answer:check[2],explanation:check[3]},sources:sources.map(([label,url])=>({label,url})),links});
export const simulationUnits=[
make('scene-assets','解释同事搭建家居、户型与场景怎样服务机器人训练，区分外观资产、可交互环境与模型。',[
 ['WorldSimReady','已核对的公开案例为 Yootta/World-SimReady-Home，提供家居场景与任务数据；同事使用的具体版本仍需对照。'],['SimReady','为目标仿真用途准备并验证资产所需属性；不是一种大模型骨干结构。'],['户型与场景图','户型规定空间布局，场景图组织房间、资产、位置及关系。'],['OpenUSD','可组合、描述和交换三维场景的体系；文件能打开不代表物理和任务都正确。'],['碰撞体与关节','分别约定接触几何和部件之间的运动限制。']],
 [
 ['为什么世界模型后面要补环境','上一部分学习了预测状态变化，但训练和验证所需的交互从哪里来？真实机器人采集昂贵且覆盖有限，于是需要可重复的模拟环境。在这里，构建房屋不是偏离模型训练，而是在定义数据与任务的来源。','你的同事可能在做资产制作、布局生成、仿真属性配置、传感器/轨迹采集或任务测试。仅凭“家居场景”不能确定是哪一步，更不能判断一定在训练导航模型。'],
 ['从一张漂亮图开始，找出它缺什么','一张客厅效果图可用于视觉任务，却没有可查询的三维坐标、碰撞或相机运动。三维场景能改变视角，但若没有正确接触属性，机器人可能穿过桌子。加上物理和传感器后仍缺任务：从哪出发、找什么、怎样算成功？','按“图像 → 三维资产 → 布局 → 可交互仿真 → 任务”的顺序排查，比看到世界一词就认为是世界模型更可靠。生成模型可能参与造资产或场景，但那只是管线中的一个模块。'],
 ['带读真实案例：WorldSimReady-Home','按照 ModelScope 线索可找到 Yootta/World-SimReady-Home。官方将它发布为数据集：CAD 资产经处理并配置物理属性，再组成家居场景；还包含机器人任务数据。它在学习路线中属于“环境与数据来源”，不是 SFT、LoRA 或 KDA 的替代品。','发布者数据集卡展示 scene 下的 USDZ 场景包、JSON 元数据和 PNG 俯视预览。PNG 帮你看布局，元数据帮助理解记录，场景包才是三维资源入口，三者不能互相替代。task 示例展示抓取放置任务的 HDF5 与 JSON/JSONL 记录，所以不能只按导航理解整个数据集。','带读任务：先不下载全量数据，在官方卡片中找到 scene 与 task 的目录；分别回答“给仿真器什么”和“给训练器什么”。卡片当前标注 CC BY-NC-SA 4.0，实际使用前核对所选版本与许可；本课程只链接和讲解资料，没有复制或打包该数据集。'],
 ['搭一间能用的房屋','先用简单盒子表示地板、墙、门、沙发和机器人，固定米制、上轴和坐标变换。检查家具不穿墙，起点不在物体内，目标附近有停留空间。外观先简单，方便看清碰撞错误。','接着按任务补属性：静态导航关心障碍与通行；推椅子需要动态接触；开柜门需要关节轴与范围。SimReady 的具体要求应看目标用途与版本，不能用一个“已就绪”标签替代运行验证。'],
 ['把工程骨架摆出来','assets/ 保存来源、单位、视觉和碰撞；scenes/ 保存布局与资产引用；sim/ 配置步长、传感器和物理；tasks/ 定义起点目标与终止；datasets/ 记录回合；models/ 训练；eval/ 做独立验证。每个目录有契约与版本，替换一个场景生成器不必重写策略训练。','工具分工的公开例子：ProcTHOR 生成与 AI2-THOR 配合的交互房屋；Habitat-Sim/Habitat-Lab 分别提供仿真与任务等能力；Isaac Sim 可承接机器人仿真和数据生成。它们不是同一层的三种模型结构，采用前要检查当前兼容性与资产许可。']
 ],
 ['假设要“从客厅去厨房门口”：输入是机器人观测与目标，动作是移动/转向，输出验收由环境判断。','只替换墙纸可测试外观变化；移动沙发堵住门，改变的是可通行结构。','给沙发去掉碰撞会让机器人穿过去，看起来任务更快完成，但这是环境错误而非算法进步。','同一批有效交互可产出动作轨迹、图像/深度/语义标签或状态转移，分别服务不同训练目标。'],
 ['为一间虚构两居室写场景清单：房间/门/家具、单位、碰撞、机器人尺寸、起点目标；按上面的目录各写应保存哪些字段。然后挑一个家具，说明导航与操纵对它的要求如何不同。','交付一份带来源与版本的场景契约，并列出三个能执行的验收：无重叠、起终点有效、通道可达。能解释每个字段由谁消费。','本节未安装或运行完整三维仿真器。公开案例已按发布者资料核对；同事是否使用相同版本、是否有额外生成管线，仍需用实际配置确认。下一节先在浏览器验证可达性机制。'],
 ['导入能显示的家居模型后，还缺什么才能判断机器人能否完成任务？',['无需别的，有画面就够了','还要检查碰撞、机器人尺寸、任务与实际执行','只需提高生成图像分辨率'],1,'外观、物理、任务与模型是不同层。画面好看并不证明能走、能交互或能成功。'],
 [['WorldSimReady-Home 官方项目','https://github.com/YoottaAI/World-SimReady-Home'],['WorldSimReady-Home 发布者数据集卡','https://huggingface.co/datasets/Yootta/World-SimReady-Home'],['ModelScope 数据集入口','https://modelscope.cn/datasets/Yootta/World-SimReady-Home'],['NVIDIA SimReady 概述','https://docs.omniverse.nvidia.com/simready/latest/'],['OpenUSD 场景描述','https://openusd.org/release/intro.html'],['ProcTHOR 官方仓库','https://github.com/allenai/procthor'],['Habitat','https://aihabitat.org/']],
 [{label:'理解 WorldSimReady-Home 的职责',href:'#/concepts/worldsimready'},{label:'下一节：从户型到导航',href:'#/book/systems/simulation/navigation-lab'}]),
make('navigation-lab','从可通行空间出发，跑通已知地图的导航基线，并解释它离视觉导航还差什么。',[
 ['占据栅格与 NavMesh','把空间变成可搜索的障碍/可通行表示；表示需要考虑机器人尺寸与运动能力。'],['导航任务','给定观测、目标和动作，让机器人移动并满足到达协议；可为位置、物体或语言目标。'],['SPL','成功加权的路径效率；失败为 0，成功时比较最短路径与实际路径长度。']],
 [
 ['地图上的空白为何仍走不过去','先让机器人是一个点，空格就能走。接着给它半径，同样的窄门可能不再可通行。因此地图不是只由房屋决定，还和机器人尺寸、允许坡度、台阶、转弯等约束有关。','栅格给每个小格标占据与否；NavMesh 用多边形组织可导航表面。两者都需要构建假设，静态地图也不能保证动态人群中始终可行。'],
 ['先给全部地图，做一个可解释基线','下面例子用已知栅格、四邻居、单位代价和 BFS（广度优先搜索：先搜一步可达，再搜两步可达）。在这些条件下可求最短步数；若距离或转弯代价不同，就需相应的加权搜索。','BFS 不是神经网络，没有参数更新。它提供最短路和故障参照：如果连这个全图基线都不可达，先修场景或任务，不要盲目调学习率。'],
 ['从已知地图到真正的导航任务','PointNav 给位置目标；ObjectNav 给物体类别，常需寻找未知位置；VLN 使用语言描述。相机、深度、定位信息和全图是否提供，都应写进任务契约。给全图和不给全图不能当相同难度横向比较。','当只提供局部观测时，还需要感知、定位/建图或记忆、探索、路径/行动选择与停止判断。可先用规则流程，再训练模仿或 RL 策略；导航不一定要求世界模型，也不一定必须用大语言模型。'],
 ['找到路径之后，验证真实执行','路径是意图，控制器要把它变成动作。记录每步观测、动作、实际位移、碰撞和结束原因；到达位置但没有按协议停止，也可能不算成功。','固定场景和任务协议报告成功率、路径效率、碰撞与超时。最短路径长度为 l、实际长度为 p，成功项为 S，则单回合 SPL=S·l/max(l,p)；本节只讨论 l>0，零距离起终点应另定义边界。']
 ],
 ['浏览器格图中，S 与 G 同行，中间四步到达，BFS 返回 4。','在直线中间放障碍，下面一行可绕行，最短步数变为 6。','再把绕行通道全部封住，返回 None，明确表示不可达；不是返回 0 假装已经到达。','若最短 4 米，实际成功走 6 米，本回合 SPL 约 0.667；若失败则是 0。路径是否碰撞也要单独报告。'],
 ['打开导航小实验，先原样运行，再把 (1,3) 设为障碍，再封闭下面一行。每次先预测结果并解释。另在纸上画半径不同的机器人，判断同一扇门何时不可通过。','得到 4、6、None 三组结果；能区分不可达、起点即目标、执行失败。说明这个例子是全图规划，不是视觉导航或策略训练。','如果始终返回 4，检查是否真的把字符写为 #；如果意外越界，检查地图与邻居边界。若要接三维仿真，再处理坐标系、机器人半径、传感器与实际 step 行为。'],
 ['机器人变宽后过不了门，应首先检查什么？',['把模型层数翻倍','地图/碰撞是否考虑新尺寸及通道连通性','把成功判定阈值改大就算解决'],1,'这是环境几何与机器人约束问题。先证实路径可执行，再分析策略是否会选它。'],
 [['Habitat 导航任务','https://aihabitat.org/'],['Habitat SPL 定义','https://aihabitat.org/docs/habitat-lab/habitat.tasks.nav.nav.SPL.html'],['导航评测原论文','https://arxiv.org/abs/1807.06757']],
 [{label:'运行并修改户型可达性例子',href:'#/code/concept-navigation'},{label:'继续：环境如何产生训练数据',href:'#/book/systems/simulation/simulation-data'}]),
make('simulation-data','把场景产物接到世界模型、策略与后训练，并设计不泄漏的评测和迁移实验。',[
 ['仿真器与环境','仿真推进状态并产生观测，环境补充任务、奖励与结束协议；学习型世界模型则从数据拟合变化。'],['合成数据','由受控生成/仿真过程产生的数据与标签，仍需检查正确性和任务覆盖。'],['域随机化','按有记录的分布改变外观、布局、物理或传感器条件。'],['Sim-to-Real','把仿真得到的能力转移到真实环境，需要识别差距并用真实结果验证。']],
 [
 ['同一间房屋怎样服务三类训练','记录 (obs_t,action_t,obs_next,dt) 可训练动作条件世界模型；记录教师行动或成功轨迹可做行为克隆；让策略在环境中交互并得到奖励可做 RL。环境供给样本与反馈，模型训练仍要明确 loss 与可训练参数。','若要做多模态 SFT，还需把任务指令、观测、动作/回答组织成示范格式，明确监督区域。若用 LoRA，则进一步选择更新参数的形式。场景数量增加并不自动完成 SFT，也不自动得到好策略。'],
 ['设计数据账本，先保留因果和时间','每条回合保存 scene_id、资产/布局版本、seed、机器人/相机参数、任务目标和结束原因；每步保存时间戳、动作单位及观测。对齐错一帧会让正确转移看起来不符合规律。','仿真状态可用于生成标签和诊断，但若部署只给 RGB，就不能偷偷把全局位置或完整状态当推理输入。训练中的特权教师也要和学生实际可得信息分开。'],
 ['怎样让一间房变成有效多样性','第一组只改墙纸、光照和材质；第二组改家具位置与户型连接；第三组按需求改噪声、摩擦或时延。分别评测，才能看出模型缺的是外观鲁棒性、空间泛化还是控制适应。','不要先随机生成一万帧再按帧划分集合。应先按独立房屋、布局或资产家族划分，再生成各集合数据；近重复场景和固定目标捷径会让评测虚高。不可达或穿插场景要按任务规则筛除或明确作为故障测试。'],
 ['怎样从仿真走向真实','先建立固定仿真集基线，再在独立布局上测；之后由团队按实际机器人测试流程验证受控真实场景。分开记录渲染差距、深度缺失、相机标定、动力学、动作延迟与控制频率。','根据失败证据选择标定、调整随机化范围、补真实数据或做任务适配。更逼真画面可能有帮助，但不是所有问题的答案；真实控制延迟不会因为墙纸更真实就消失。'],
 ['闭环回到下一章的策略','现在已经有可检查的资产、有效任务、数据与评测协议。下一章才问“怎样根据观测选择动作”：行为克隆、VLA、Diffusion Policy 或规划会利用不同信息。','完整三维场景生成、Isaac Sim/Habitat 安装、真实机器人训练尚未在本平台执行；本章已提供接口设计、带练代码与验收方法，后续完整实战需要交付具体版本、运行日志和实测结果。']
 ],
 ['场景 A 固定沙发位置，训练策略总向左转也可能高成功；将沙发移右后失败，暴露位置捷径。','保存同一轨迹供世界模型训练时，目标是动作后的下一状态；供 BC 时，目标是当前观测下的教师动作。','增加奖励并不会自动产生 RL 更新：还要明确采样、回报/优势、优化目标与参数 step。','对同场景不同墙纸有效，只支持外观变化结论；迁移到新户型和真实家庭必须分别取证。'],
 ['提交一份场景→回合→三类训练样本的字段表；为世界模型、BC、RL 各写输入、监督信号、模型更新和评测。设计固定布局/新布局/受控真实三层评测，标明目前实际完成哪层。','数据含版本和时间对齐；学生不读部署不可得的状态；按独立房屋划分；结论与证据对应，不把截图或样本数当作模型效果。','发现效果差先区分：环境有效性、数据契约、目标与实现、优化、泛化。不要因为仿真数据可无限生成就省略小样本过拟合与独立验证。'],
 ['同一户型换不同纹理，随机按帧分训练测试，能证明什么？',['证明真实家庭泛化','可能存在近重复泄漏，不能证明新户型或真实泛化','自动证明 SFT 成功'],1,'划分单位决定结论范围。先按独立场景划分，分别验证外观、结构与真实差距。'],
 [['Isaac Sim 场景合成数据教程','https://docs.isaacsim.omniverse.nvidia.com/latest/replicator_tutorials/tutorial_replicator_scene_based_sdg.html'],['域随机化原论文','https://arxiv.org/abs/1703.06907'],['Habitat 任务与学习','https://aihabitat.org/']],
 [{label:'回到模型训练全生命周期',href:'#/book/training/overview/three-stages'},{label:'下一步：策略与行为克隆',href:'#/book/systems/robot/policy'}])
];
